import type { ResolvedConfig } from "./config.js";
import {
  errorFromResponse,
  VatlyApiError,
  VatlyConnectionError,
  VatlyError,
  VatlyTimeoutError,
} from "./errors.js";

const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);
/** Mutating methods that should carry an Idempotency-Key (auto-generated by default). */
const IDEMPOTENT_METHODS = new Set(["POST", "PATCH"]);

export interface RequestOptions {
  /** Optional idempotency key for mutating calls; sent as `Idempotency-Key`. */
  idempotencyKey?: string;
  /** Per-call timeout override (ms). Falls back to client config. */
  timeoutMs?: number;
  /** Extra headers; merged over client defaults. */
  headers?: Record<string, string>;
  /** AbortSignal merged with the timeout signal. */
  signal?: AbortSignal;
}

/**
 * Sleep with jittered exponential backoff.
 * Used between retry attempts. `attempt` is 0-indexed (first retry = 0).
 */
function backoffDelay(attempt: number, retryAfterSec?: number): number {
  if (retryAfterSec && retryAfterSec > 0) {
    // Cap server-supplied delay at 60s to avoid pathological waits.
    return Math.min(retryAfterSec * 1000, 60_000);
  }
  const base = 250 * 2 ** attempt; // 250ms, 500ms, 1s, 2s, ...
  const capped = Math.min(base, 8_000);
  const jitter = Math.random() * capped * 0.25;
  return capped + jitter;
}

function parseRetryAfter(header: string | null): number | undefined {
  if (!header) return undefined;
  const asInt = Number.parseInt(header, 10);
  if (Number.isFinite(asInt) && asInt >= 0) return asInt;
  // HTTP-date form: convert to seconds-from-now.
  const asDate = Date.parse(header);
  if (Number.isFinite(asDate)) {
    return Math.max(0, Math.ceil((asDate - Date.now()) / 1000));
  }
  return undefined;
}

export interface RawRequest {
  method: string;
  /** Path relative to baseUrl, e.g. "/checkouts" or "/orders/order_123". */
  path: string;
  /** Query parameters; values are stringified, arrays produce repeated keys. */
  query?: Record<string, unknown>;
  /** JSON body — serialized as application/json. */
  body?: unknown;
}

export type FetchMiddleware = (
  req: RawRequest,
  options: RequestOptions,
  config: ResolvedConfig,
) => Promise<Response>;

/**
 * Execute a request with auth, timeout, idempotency, retries, and error mapping.
 * Returns the parsed JSON body on success (or `undefined` for 204).
 */
export async function performRequest<T>(
  req: RawRequest,
  options: RequestOptions,
  config: ResolvedConfig,
): Promise<T> {
  const url = buildUrl(config.baseUrl, req.path, req.query);
  const method = req.method.toUpperCase();
  const safe = SAFE_METHODS.has(method);

  // Resolve the Idempotency-Key value (caller > auto-generator > none).
  // POST and PATCH get auto-keys by default — matches vatly/vatly-api-php.
  let idempotencyKey = options.idempotencyKey;
  if (idempotencyKey === undefined && IDEMPOTENT_METHODS.has(method) && config.idempotencyKeyGenerator) {
    idempotencyKey = config.idempotencyKeyGenerator();
  }
  const hasIdemKey = typeof idempotencyKey === "string" && idempotencyKey.length > 0;
  // Per spec guidance: never retry non-idempotent POST/PATCH without an idempotency key.
  const retryable = safe || hasIdemKey;

  const baseHeaders: Record<string, string> = {
    Authorization: `Bearer ${config.apiKey}`,
    Accept: "application/json",
    "User-Agent": config.userAgent,
    ...config.defaultHeaders,
    ...options.headers,
  };

  if (config.clientInfoHeader) {
    baseHeaders["X-Vatly-Client-Info"] = config.clientInfoHeader;
  }

  if (req.body !== undefined) {
    baseHeaders["Content-Type"] = "application/json";
  }
  if (hasIdemKey) {
    baseHeaders["Idempotency-Key"] = idempotencyKey!;
  }

  const serializedBody = req.body === undefined ? undefined : JSON.stringify(req.body);
  const timeoutMs = options.timeoutMs ?? config.timeoutMs;

  let lastError: unknown;
  const maxAttempts = retryable ? config.maxRetries + 1 : 1;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const { signal, cancel } = makeSignal(timeoutMs, options.signal);
    try {
      const response = await config.fetch(url, {
        method,
        headers: baseHeaders,
        body: serializedBody,
        signal,
      });
      cancel();

      if (response.ok) {
        return (await parseResponse<T>(response)) as T;
      }

      const retryAfter = parseRetryAfter(response.headers.get("Retry-After"));
      const shouldRetry =
        retryable &&
        attempt < maxAttempts - 1 &&
        (response.status === 429 || response.status >= 500);

      if (shouldRetry) {
        await sleep(backoffDelay(attempt, retryAfter));
        continue;
      }

      throw await errorFromHttpResponse(response, url, method, retryAfter);
    } catch (err) {
      cancel();
      if (err instanceof VatlyError) {
        if (!(retryable && attempt < maxAttempts - 1 && err.status >= 500)) {
          throw err;
        }
        lastError = err;
        await sleep(backoffDelay(attempt));
        continue;
      }

      // Network-layer failure or abort.
      const isAbort = isAbortError(err);
      if (isAbort && options.signal?.aborted) {
        throw new VatlyConnectionError("Request aborted by caller.", err);
      }
      if (isAbort) {
        const timeoutErr = new VatlyTimeoutError(timeoutMs, err);
        if (retryable && attempt < maxAttempts - 1) {
          lastError = timeoutErr;
          await sleep(backoffDelay(attempt));
          continue;
        }
        throw timeoutErr;
      }

      const connErr = new VatlyConnectionError(
        err instanceof Error ? err.message : "Network request failed.",
        err,
      );
      if (retryable && attempt < maxAttempts - 1) {
        lastError = connErr;
        await sleep(backoffDelay(attempt));
        continue;
      }
      throw connErr;
    }
  }

  // Should be unreachable, but TypeScript can't prove it.
  throw lastError instanceof Error
    ? lastError
    : new VatlyApiError({ status: 0, url, method });
}

async function parseResponse<T>(response: Response): Promise<T | undefined> {
  if (response.status === 204) return undefined;
  const text = await response.text();
  if (text.length === 0) return undefined;
  try {
    return JSON.parse(text) as T;
  } catch {
    // The spec contract is JSON; a non-JSON 2xx is a server bug — surface raw.
    return text as unknown as T;
  }
}

async function errorFromHttpResponse(
  response: Response,
  url: string,
  method: string,
  retryAfter: number | undefined,
): Promise<VatlyError> {
  const text = await response.text();
  let body: unknown;
  try {
    body = text.length > 0 ? JSON.parse(text) : undefined;
  } catch {
    body = text;
  }
  const requestId = response.headers.get("X-Request-Id") ?? undefined;
  return errorFromResponse({
    status: response.status,
    requestId,
    body: body as never,
    url,
    method,
    retryAfter,
  });
}

function makeSignal(
  timeoutMs: number,
  external: AbortSignal | undefined,
): { signal: AbortSignal; cancel: () => void } {
  const controller = new AbortController();
  const onAbort = () => controller.abort(external?.reason);
  if (external) {
    if (external.aborted) {
      controller.abort(external.reason);
    } else {
      external.addEventListener("abort", onAbort, { once: true });
    }
  }
  const timer =
    timeoutMs > 0
      ? setTimeout(() => controller.abort(new Error("timeout")), timeoutMs)
      : undefined;

  return {
    signal: controller.signal,
    cancel: () => {
      if (timer) clearTimeout(timer);
      if (external) external.removeEventListener("abort", onAbort);
    },
  };
}

function isAbortError(err: unknown): boolean {
  if (!err || typeof err !== "object") return false;
  const name = (err as { name?: unknown }).name;
  return name === "AbortError" || name === "TimeoutError";
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function buildUrl(
  baseUrl: string,
  path: string,
  query: Record<string, unknown> | undefined,
): string {
  const url = new URL(`${baseUrl}${path.startsWith("/") ? path : `/${path}`}`);
  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value === undefined || value === null) continue;
      if (Array.isArray(value)) {
        for (const v of value) {
          if (v === undefined || v === null) continue;
          url.searchParams.append(key, String(v));
        }
      } else {
        url.searchParams.set(key, String(value));
      }
    }
  }
  return url.toString();
}
